from collections import defaultdict, deque

class Solution:

	def substrCount(self, s, k):

		def tempFunc(s, k):
			if k == 0:
				return 0
			result = 0
			mp = defaultdict(int)
			cnt = 0
			dq = deque()
			for i in s:
				if cnt == k and mp[i] == 0:
					while cnt == k:
						mp[dq[0]] -= 1
						if mp[dq[0]] == 0:
							cnt -= 1
						dq.popleft()
					mp[i] += 1
					cnt += 1
					dq.append(i)
					result += len(dq)
				else:
					if mp[i] == 0:
						cnt += 1
					mp[i] += 1
					dq.append(i)
					result += len(dq)
			return result
		return tempFunc(s, k) - tempFunc(s, k - 1)
